#include "task.h"

#include <algorithm>

#include "state_lock.h"
#include "util.h"

namespace tea {

namespace task_status {
const char* const kQueued = "queued";
const char* const kRunning = "running";
const char* const kWaitingConfirmation = "waiting_confirmation";
const char* const kDone = "done";
const char* const kFailed = "failed";
const char* const kCancelled = "cancelled";
}  // namespace task_status

namespace {

/// The file of one task. The id is generated by us and only contains
/// [a-z0-9_], so it cannot escape the directory.
std::string task_file(const std::string& dir, const std::string& id) {
  return path_join(dir, id + ".json");
}

}  // namespace

nlohmann::json Task::to_json() const {
  nlohmann::json j = nlohmann::json::object();
  j["id"] = id;
  j["workspace_id"] = workspace_id;
  j["session_id"] = session_id;
  j["title"] = title;
  j["prompt"] = prompt;
  j["status"] = status;
  j["progress"] = progress;
  j["note"] = note;
  j["steps"] = steps;
  j["needs_confirmation"] = needs_confirmation;
  j["question"] = question;
  j["provider"] = provider;
  j["model"] = model;
  j["created_at"] = created_at;
  j["updated_at"] = updated_at;
  j["started_at"] = started_at;
  j["finished_at"] = finished_at;
  j["error"] = error;
  j["meta"] = meta;
  return j;
}

Task Task::from_json(const nlohmann::json& j) {
  Task t;
  auto str = [&](const char* key) -> std::string {
    auto it = j.find(key);
    return (it != j.end() && it->is_string()) ? it->get<std::string>() : std::string();
  };
  t.id = str("id");
  t.workspace_id = str("workspace_id");
  t.session_id = str("session_id");
  t.title = str("title");
  t.prompt = str("prompt");
  t.status = str("status");
  if (t.status.empty()) t.status = task_status::kQueued;
  auto pit = j.find("progress");
  if (pit != j.end() && pit->is_number()) t.progress = pit->get<int>();
  t.note = str("note");
  auto sit = j.find("steps");
  if (sit != j.end() && sit->is_array()) t.steps = *sit;
  auto cit = j.find("needs_confirmation");
  if (cit != j.end() && cit->is_boolean()) t.needs_confirmation = cit->get<bool>();
  t.question = str("question");
  t.provider = str("provider");
  t.model = str("model");
  t.created_at = str("created_at");
  t.updated_at = str("updated_at");
  t.started_at = str("started_at");
  t.finished_at = str("finished_at");
  t.error = str("error");
  auto mit = j.find("meta");
  if (mit != j.end() && mit->is_object()) t.meta = *mit;
  return t;
}

std::string TaskStore::dir_for(const Workspace& ws) {
  return path_join(ws.run_dir(), "tasks");
}

bool TaskStore::create(const Workspace& ws, Task* task, std::string* err) {
  StateLock lock(state_mutex());
  const std::string dir = dir_for(ws);
  if (!make_dirs(dir)) {
    if (err) *err = "cannot create " + dir;
    return false;
  }
  // The caller fills in what the task is; the store owns the identity and the
  // timestamps.
  task->id = make_id("t_");
  task->workspace_id = ws.id();
  task->status = task_status::kQueued;
  task->created_at = now_iso8601();
  task->updated_at = task->created_at;
  return save(ws, *task, err);
}

bool TaskStore::load(const Workspace& ws, const std::string& id, Task* out, std::string* err) {
  StateLock lock(state_mutex());
  const std::string path = task_file(dir_for(ws), id);
  std::string text;
  if (!read_file(path, &text, 1024u * 1024u)) {
    if (err) *err = "task not found: " + id;
    return false;
  }
  nlohmann::json j = nlohmann::json::parse(text, nullptr, false);
  if (!j.is_object()) {
    if (err) *err = "task file is not valid JSON: " + path;
    return false;
  }
  if (out) *out = Task::from_json(j);
  return true;
}

bool TaskStore::save(const Workspace& ws, const Task& task, std::string* err) {
  const std::string dir = dir_for(ws);
  if (!make_dirs(dir)) {
    if (err) *err = "cannot create " + dir;
    return false;
  }
  Task t = task;
  t.updated_at = now_iso8601();
  // Atomic replace: a reader (the scheduler polling the list) never sees half a
  // task file.
  return write_file_atomic(task_file(dir, t.id), t.to_json().dump(2) + "\n", err);
}

bool TaskStore::update(const Workspace& ws, const std::string& id,
                       const std::function<void(Task*)>& fn, Task* out, std::string* err) {
  StateLock lock(state_mutex());
  const std::string path = task_file(dir_for(ws), id);
  std::string text;
  if (!read_file(path, &text, 1024u * 1024u)) {
    if (err) *err = "task not found: " + id;
    return false;
  }
  nlohmann::json j = nlohmann::json::parse(text, nullptr, false);
  if (!j.is_object()) {
    if (err) *err = "task file is not valid JSON: " + path;
    return false;
  }
  Task t = Task::from_json(j);
  fn(&t);
  t.updated_at = now_iso8601();
  if (!write_file_atomic(path, t.to_json().dump(2) + "\n", err)) return false;
  if (out) *out = t;
  return true;
}

std::vector<Task> TaskStore::list(const Workspace& ws) {
  StateLock lock(state_mutex());
  std::vector<Task> out;
  std::vector<DirEntryInfo> files;
  std::string err;
  const std::string dir = dir_for(ws);
  if (!list_directory(dir, &files, &err)) return out;
  for (std::size_t i = 0; i < files.size(); ++i) {
    if (files[i].is_dir) continue;
    if (path_extension(files[i].name) != ".json") continue;
    std::string text;
    if (!read_file(files[i].path, &text, 1024u * 1024u)) continue;
    nlohmann::json j = nlohmann::json::parse(text, nullptr, false);
    if (!j.is_object()) continue;
    out.push_back(Task::from_json(j));
  }
  // Newest first: the list is read by a human as often as by the scheduler.
  std::sort(out.begin(), out.end(), [](const Task& a, const Task& b) {
    if (a.created_at != b.created_at) return a.created_at > b.created_at;
    return a.id > b.id;
  });
  return out;
}

std::vector<Task> TaskStore::list_by_status(const Workspace& ws, const std::string& status) {
  std::vector<Task> all = list(ws);
  std::vector<Task> out;
  for (std::size_t i = 0; i < all.size(); ++i) {
    if (all[i].status == status) out.push_back(all[i]);
  }
  // Oldest first: that is the order the work is done in.
  std::sort(out.begin(), out.end(), [](const Task& a, const Task& b) {
    if (a.created_at != b.created_at) return a.created_at < b.created_at;
    return a.id < b.id;
  });
  return out;
}

}  // namespace tea
